// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPlenty {
    function owner() external view returns (address);
    function _taxFee() external view returns (uint256);
    function _liquidityFee() external view returns (uint256);
    function _maxTxAmount() external view returns (uint256);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function setMaxTxPercent(uint256 maxTxPercent) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);
    IPlenty plenty;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        plenty = IPlenty(TARGET);
        vm.label(TARGET, "PlentyCoin");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = plenty.owner();
        vm.label(owner, "Owner");

        // Record initial tax fee
        uint256 initialTaxFee = plenty._taxFee();

        // Impersonate owner and modify tax fee (no event emitted!)
        vm.startPrank(owner);
        plenty.setTaxFeePercent(50); // Change from default 5 to 50
        vm.stopPrank();

        // Verify state was modified
        uint256 newTaxFee = plenty._taxFee();

        // Oracle check: tax fee was modified without event
        assertGt(newTaxFee, initialTaxFee, "Tax fee should be increased");
        assertTrue(newTaxFee != initialTaxFee, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
